-- Hand-written migration (NOT generated by `prisma migrate dev`).
-- Prisma's schema language cannot express PARTIAL (filtered) unique indexes --
-- `@@unique` has no predicate argument as of Prisma 6.19.1 -- so this index is
-- maintained manually, separate from the generated baseline. Same mechanics
-- as _stock_non_negative.
--
-- WARNING, stronger than the CHECK case: indexes ARE part of Prisma's managed
-- surface. A future `prisma migrate dev` compares the shadow DB (which
-- replays this file) against schema.prisma, finds an index the PSL does not
-- declare, and WILL emit a `DROP INDEX "CashRegister_one_open_per_store";`
-- line in the generated migration. That line MUST be deleted by hand.
-- tests/integrity/caja-open-index.test.js is what catches you if you forget.
CREATE UNIQUE INDEX "CashRegister_one_open_per_store"
  ON "CashRegister" ("storeId")
  WHERE "status" = 'OPEN';
